import re, textwrap

def grids_from_msg(msg):
 pairs=[]
 for n in (1,2,3):
  im=re.search(rf'Demo pair {n} input \(\d+x\d+\):\n(.*?)(?=\nDemo pair {n} output)',msg,re.S)
  om=re.search(rf'Demo pair {n} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance)',msg,re.S)
  if im and om:
   def parse(s): return [[int(v) for v in row.split()] for row in s.strip().splitlines()]
   pairs.append((parse(im.group(1)),parse(om.group(1))))
 return pairs
